                    "diff --git a/src/lib/gssapi/spnego/negoex_util.c b/src/lib/gssapi/spnego/negoex_util.c\010index edc5462e84..a65238e573 100644\010--- a/src/lib/gssapi/spnego/negoex_util.c\010+++ b/src/lib/gssapi/spnego/negoex_util.c\010@@ -253,6 +253,10 @@ parse_nego_message(OM_uint32 *minor, struct k5input *in,\010     offset = k5_input_get_uint32_le(in);\010     count = k5_input_get_uint16_le(in);\010     p = vector_base(offset, count, EXTENSION_LENGTH, msg_base, msg_len);\010+    if (p == NULL) {\010+        *minor = ERR_NEGOEX_INVALID_MESSAGE_SIZE;\010+        return GSS_S_DEFECTIVE_TOKEN;\010+    }\010     for (i = 0; i < count; i++) {\010         extension_type = load_32_le(p + i * EXTENSION_LENGTH);\010         if (extension_type & EXTENSION_FLAG_CRITICAL) {\010@@ -391,7 +395,8 @@ parse_message(OM_uint32 *minor, spnego_gss_ctx_id_t ctx, struct k5input *in,\010     msg_len = k5_input_get_uint32_le(in);\010     conv_id = k5_input_get_bytes(in, GUID_LENGTH);\010 \010-    if (in->status || msg_len > token_remaining || header_len > msg_len) {\010+    if (in->status || msg_len > token_remaining ||\010+        header_len < (size_t)(in->ptr - msg_base) || header_len > msg_len) {\010         *minor = ERR_NEGOEX_INVALID_MESSAGE_SIZE;\010         return GSS_S_DEFECTIVE_TOKEN;\010     }\010",
